/**
 * Helpers for filter components (Blur, ColorAdjust): add or remove one filter without disturbing
 * the others, so several filter components can live on the same object.
 *
 * Generated by Pixi Editor (components v1). Plain TypeScript: safe to read, edit and commit.
 */
import type { Container, Filter } from "pixi.js";

/** The object's filters as a fresh array (Pixi stores one filter, a list, or none). */
function list(target: Container): Filter[] {
  const current = target.filters;
  if (!current) return [];
  return ([] as Filter[]).concat(current);
}

/** Replaces `old` (if present) with `next`, keeping any filters other components added. */
export function setFilter(
  target: Container,
  old: Filter | null,
  next: Filter,
): void {
  const kept = old ? list(target).filter((f) => f !== old) : list(target);
  kept.push(next);
  target.filters = kept;
}

/** Removes `filter` from the object, leaving the rest in place. */
export function clearFilter(target: Container, filter: Filter | null): void {
  if (!filter) return;
  target.filters = list(target).filter((f) => f !== filter);
}
